import json

pairs = [
    ("tut", "tuot"), ("ura", "ura"), ("dunna", "duonna"), ("num", "nom"),
    ("nums", "noms"), ("insumma", "insomma"), ("numer", "nomer"),
    ("buglia", "buoglia"), ("discuors", "discuors"), ("puolpa", "puolpa"),
    ("angul", "angul"), ("fuorma", "fuorma"), ("flur", "flur"),
    ("fuorcla", "fuorcla"),
]

# Attested regular differences between the columns (Sursilvan -> Engadine)
changes = {}
for s, e in pairs:
    if s != e:
        if "uo" in e and "uo" not in s:
            changes.setdefault("u->uo", []).append((s, e))
        elif "o" in e and "u" in s:
            changes.setdefault("u->o before nasal", []).append((s, e))

target_engadine = "cuort"

# A word with uo in both dialects would be listed identically; blank (3) is in the
# Sursilvan column, where the only attested non-nasal difference is u (Surs.) -> uo (Eng.).
# Invert that correspondence for the stressed vowel.
answer = target_engadine.replace("uo", "u", 1)

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "rule": "Sursilvan u -> Engadine uo (tut/tuot, dunna/duonna, buglia/buoglia); "
                "before nasal m/n -> o (num/nom, numer/nomer, insumma/insomma)",
        "changes_found": changes,
        "engadine_form": target_engadine,
        "caveat": "uo is also kept in some words (fuorcla, discuors), so the choice of u is a heuristic; the data cannot rule out cuort",
    }
}))
